import{_ as o,l as t,o as e,c as l,v as r,p as s,x as n,d,i as h,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Sennrich BPE 论文","description":"","frontmatter":{"title":"Sennrich BPE 论文","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sennrich-bpe.md","filePath":"llm/sennrich-bpe.md","lastUpdated":1789023840000}'),c={name:"llm/sennrich-bpe.md"};function p(B,a,A,m,u,P){const i=t("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="sennrich-bpe-论文" tabindex="-1">Sennrich BPE 论文 <a class="header-anchor" href="#sennrich-bpe-论文" aria-label="Permalink to &quot;Sennrich BPE 论文&quot;">​</a></h1><div class="epigraph"><p>把稀有词切成训练中反复出现的子词单位，神经翻译就不必为开放词表里每一个未见词准备一套对策。</p><footer>—— Sennrich, Haddow, Birch, Neural Machine Translation of Rare Words with Subword Units, ACL 2016</footer></div><p><a href="/llm/subword-history">上一篇附录</a> 把 GloVe 之后的子词写成词表史。本篇对照 <strong>Sennrich、Haddow、Birch 的 ACL 2016 原文</strong>：在神经机器翻译上用字节对编码（BPE）学子词。主干课 <a href="/llm/tokenizer-design">Tokenizer 设计</a> 用当代实现；这里只钉论文问了什么、实验怎么写、边界在哪。不发明编号，出处就是 ACL 2016 这篇。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>词级 NMT 把未登录词交给拷贝、字符回退或截短词表。德语复合词、形态变化把大量质量送到 UNK。作者要一种<strong>固定大小、对任意词可分解、高频词仍可保留为原子</strong>的符号。BPE 原是数据压缩的合并算法（Gage），他们把它改成词表学习：在词频表上反复合并最常见相邻对，直到达到目标操作数。</p><p>相对纯字符模型，子词更短、更易对齐；相对整词，开放词表被覆盖。问题设定是翻译质量与 UNK 率，不是后来 LLM 的压缩率–下游曲线。</p><h3 id="在词频上合并-不是在整句字节上" tabindex="-1">在词频上合并，不是在整句字节上 <a class="header-anchor" href="#在词频上合并-不是在整句字节上" aria-label="Permalink to &quot;在词频上合并，不是在整句字节上&quot;">​</a></h3><p>他们先按空格与标点得到词，再在词内做 BPE。这保留了词边界先验。SentencePiece 后来可以在无空格生语料上直接学；那是后文，不是 2016 设定。<span class="marginnote">BPE 的学习目标不是似然，是贪心压缩启发式。没有「最优词表」定理。合并次数是超参：太少剩大量 UNK 式稀有词，太多接近字符级。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="合并程序与联合词表" tabindex="-1">合并程序与联合词表 <a class="header-anchor" href="#合并程序与联合词表" aria-label="Permalink to &quot;合并程序与联合词表&quot;">​</a></h3><p>从字符词表出发，统计相邻符号对频率，每次合并全局最高频对，加入词表。编码时对每个词贪心应用同一套合并。源、目标可分开学或联合学；他们讨论了联合 BPE 以共享子词、利于拷贝专名。</p><p>系统是当时的注意力 encoder–decoder，不是 Transformer LLM。评测用 BLEU 与 UNK 统计。对照是词级基线与其他切分。</p>',12)),(e(),s(E,null,{default:n(()=>[h(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E5%AD%97%E7%AC%A6%E7%BA%A7%E8%AF%8D%E9%A2%91%E8%A1%A8%22%5D%20--%3E%20M%5B%22%E5%8F%8D%E5%A4%8D%E5%90%88%E5%B9%B6%E6%9C%80%E9%AB%98%E9%A2%91%E7%9B%B8%E9%82%BB%E5%AF%B9%22%5D%0A%20%20M%20--%3E%20BPE%5B%22%E5%AD%90%E8%AF%8D%E8%AF%8D%E8%A1%A8%22%5D%0A%20%20W%5B%22%E8%BE%93%E5%85%A5%E8%AF%8D%22%5D%20--%3E%20E%5B%22%E8%B4%AA%E5%BF%83%E5%BA%94%E7%94%A8%E5%90%88%E5%B9%B6%E8%A7%84%E5%88%99%22%5D%0A%20%20BPE%20--%3E%20E%0A%20%20E%20--%3E%20NMT%5B%22%E6%B3%A8%E6%84%8F%E5%8A%9B%E7%BF%BB%E8%AF%91%E6%A8%A1%E5%9E%8B%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>高频词很少被切开，梯度集中在稳定原子上；稀有词共享子词参数，形态与词干可以迁移。联合 BPE 让源侧未见专名在目标侧仍有相同碎片，拷贝更容易。这是翻译对齐，不是语言建模的压缩率论证。</p><p>解码端任意字符串都可切，理论上消灭 UNK。实际仍受合并规则与预处理（是否把大小写、BPE dropout 当时还没有）约束。Kudo 下一篇会批评「单一切分」的过拟合，本篇默认训练与推理同一套贪心切分。</p><p><span class="marginnote">不要把 2016 BPE 与 GPT-2 / tiktoken 的字节级 BPE 混成一篇。后者在 UTF-8 字节上合并，处理无空格与噪声不同。机制课对照的是算法祖先，不是同一套预处理脚本。</span></p><h3 id="与当代词表课的差" tabindex="-1">与当代词表课的差 <a class="header-anchor" href="#与当代词表课的差" aria-label="Permalink to &quot;与当代词表课的差&quot;">​</a></h3><p>当代 LLM 关心 \\(|V|\\) 与压缩率、多语言公平。Sennrich 等人关心 WMT 上的 BLEU 与稀有词翻译。数字不可横向搬到 Llama 词表。对照价值是：开放词表问题被明确写成子词学习问题，并给出可复现的合并程序。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>贪心合并对语料敏感：多语言拼在一起，高频语言吃掉合并额度。他们主要在双语翻译设定下工作。没有 dropout 式多切分，分词噪声会进模型。字符级语言与无空格语言的空格先验不成立，需要后继工作。</p><p>论文不讨论百万级词表的 softmax 费用，也不讨论字节回退。那些是 ByT5、大词表 LM 的问题。引用本篇请钉 NMT 与稀有词，不要写成「LLM tokenizer 的原论文」——它是子词进入神经翻译的关键实验，谱系上的祖先，不是现代训练栈的说明书。</p><p><span class="marginnote">完整题名 <em>Neural Machine Translation of Rare Words with Subword Units</em>。作者 Rico Sennrich、Barry Haddow、Alexandra Birch。会议 ACL 2016。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>论文用 BPE 合并在 NMT 上学固定子词词表，覆盖稀有词、降低 UNK。</li><li>在词频表上贪心合并；可源–目标联合以利专名。</li><li>切分训练–推理一致；尚未引入子词正则。</li><li>评测是翻译 BLEU，不是 LLM 压缩率。</li><li>出处：Sennrich, Haddow, Birch, ACL 2016。</li></ul>',12))])}const b=o(c,[["render",p]]);export{f as __pageData,b as default};
